// src/components/SvgFlow.js
import React, { useEffect, useRef } from "react";
import * as d3 from "d3";

export default function SvgFlow({ graph }) {
  const svgRef = useRef();

  useEffect(() => {
    if (!graph) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove(); // clear previous chart

    const width = 800;
    const height = 400;
    const nodeGap = 70;

    svg
      .attr("width", width)
      .attr("height", height)
      .style("background", "#111")
      .style("border-radius", "12px");

    const group = svg.append("g").attr("transform", "translate(50,50)");

    // Draw nodes
    graph.nodes.forEach((node, i) => {
      group
        .append("rect")
        .attr("x", 100)
        .attr("y", i * nodeGap)
        .attr("width", 300)
        .attr("height", 40)
        .attr("fill", "#4b0082")
        .attr("rx", 8)
        .attr("ry", 8);

      group
        .append("text")
        .attr("x", 120)
        .attr("y", i * nodeGap + 25)
        .attr("fill", "white")
        .attr("font-size", "14px")
        .text(node.text);

      if (i > 0) {
        group
          .append("line")
          .attr("x1", 250)
          .attr("y1", i * nodeGap - 30)
          .attr("x2", 250)
          .attr("y2", i * nodeGap)
          .attr("stroke", "#fff")
          .attr("stroke-width", 2)
          .attr("marker-end", "url(#arrow)");
      }
    });

    // Add arrow marker
    const defs = svg.append("defs");
    defs
      .append("marker")
      .attr("id", "arrow")
      .attr("markerWidth", 10)
      .attr("markerHeight", 10)
      .attr("refX", 6)
      .attr("refY", 3)
      .attr("orient", "auto")
      .append("path")
      .attr("d", "M0,0 L0,6 L9,3 z")
      .attr("fill", "white");
  }, [graph]);

  return <svg ref={svgRef}></svg>;
}
